// Only the ordinary browser's DSH event/stream mux uses a LAN ticket.
function dshaPrepareLanMux(transport) {
  if (transport != null || typeof document === "undefined" || globalThis.location?.protocol !== "https:") return;
  const target = new URL("api/remote.mux", document.baseURI);
  if (target.origin !== globalThis.location.origin || target.username || target.password) return;
  const issuer = new URL("/__dsha/lan/ws-ticket", target);
  target.protocol = "wss:";
  let recognized = false;
  return async function prepare(signal) {
    const response = await fetch(issuer, {
      method: "POST", credentials: "same-origin", cache: "no-store", redirect: "error", signal,
      headers: { "X-Dsha-WebSocket-Path": target.pathname }
    });
    const transportVersion = response.headers.get("X-Dsha-Lan-Transport");
    if (transportVersion === null && !recognized) return;
    recognized = true;
    if (transportVersion !== "v1" || response.status !== 200) throw new Error("LAN WebSocket authorization failed");
    const { protocol } = await response.json();
    if (typeof protocol !== "string" || !/^dsha-lan-ticket-v1\.[A-Za-z0-9_-]{43}$/.test(protocol))
      throw new Error("Invalid LAN WebSocket authorization");
    return () => new WebSocket(target.href, ["dsha-lan-v1", protocol]);
  };
}
